package com.fantamomo.mc.amongus.advancement.utils.step

import com.fantamomo.mc.amongus.advancement.AdvancementSequenceRunner
import com.fantamomo.mc.amongus.advancement.ExperimentalAdvancementApi

/**
 * Compile-time information about a single `step(...)` call inside a runner.
 *
 * Instances are generated by the `advancement-compiler-plugin`, the runner is never executed for this.
 *
 * # Adding a new parameter
 *
 * Every constructor parameter (except [children]) is filled with the argument of the `step(...)` parameter
 * **with the same name**. To add a new piece of information:
 * 1. add the parameter to [step]
 * 2. add a constructor parameter with the same name (and a compatible type) here
 *
 * The plugin needs no changes. If the argument is omitted at the call site, the default value of the parameter here is used,
 * so every parameter that is optional in [step] must have a default here as well.
 * Arguments must be compile-time constants.
 *
 * @author Fantamomo
 * @since 2.5-SNAPSHOT
 */
@ExperimentalAdvancementApi
class StepInfo(
    val key: String,
    languageKey: String? = null,
    children: Array<StepInfo> = emptyArray(),
) {
    /**
     * The language key that was explicitly passed to [step], `null` if the default should be used.
     *
     * @see languageKey
     */
    val declaredLanguageKey: String? = languageKey


    /** The steps that are lexically nested inside this step, in source order. */
    val children: List<StepInfo> = children.asList()

    /** The step this step is nested in, `null` for top-level steps. */
    var parent: StepInfo? = null
        private set

    /** The runner this step belongs to. */
    lateinit var runner: AdvancementSequenceRunner
        private set

    /** The index of this step among its siblings. */
    var index: Int = 0
        private set

    /** The nesting depth of this step, `0` for top-level steps. */
    val depth: Int
        get() = parent?.let { it.depth + 1 } ?: 0

    /** The language key describing this step, either the [declared][declaredLanguageKey] one or the default. */
    val languageKey: String by lazy {
        declaredLanguageKey ?: defaultLanguageKey(runner.advancement.id, key)
    }

    /** This step and all nested steps in pre-order (parents before their children). */
    fun flatten(): Sequence<StepInfo> = sequence {
        yield(this@StepInfo)
        for (child in children) yieldAll(child.flatten())
    }

    internal fun bind(runner: AdvancementSequenceRunner, parent: StepInfo?, index: Int) {
        this.runner = runner
        this.parent = parent
        this.index = index
        for ([childIndex, child] in children.withIndex()) child.bind(runner, this, childIndex)
    }

    override fun toString() = "StepInfo(key=$key, children=$children)"

    companion object {
        fun defaultLanguageKey(advancementId: String, key: String) = "advancement.$advancementId.part.$key"
    }
}
